package work.tokenpro.client;

/** Embedded artwork keeps class-only updates independent of old installer resources. */
final class ApplicationArtwork {
    static final java.awt.image.BufferedImage CODEX = decode(new String[]{
        "",
        "",
        ""
    });
    static final java.awt.image.BufferedImage CLAUDE = decode(new String[]{
        "",
        "",
        ""
    });
    static final java.awt.image.BufferedImage COMMAND = decode(new String[]{
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    });
    private static java.awt.image.BufferedImage decode(String[] chunks) {
        try {
            return javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(
                java.util.Base64.getDecoder().decode(String.join("", chunks))));
        } catch (java.io.IOException exception) { throw new ExceptionInInitializerError(exception); }
    }
}
